from pathlib import Path
import re

p=Path('TehranSupermarket/shop.php')
s=p.read_text(encoding='utf-8')

s=re.sub(r'<style id="tm-visual-v28">.*?</style>\s*','',s,flags=re.S)
s=re.sub(r'<button id="tm-ai-float-v28".*?<script id="tm-ai-script-v28">.*?</script>\s*','',s,flags=re.S)

css=r'''<style id="tm-visual-v28">
.tm-ref-hero{background:#080a0d url('tehran_visual_asset.php?asset=hero&v=28') center center/cover no-repeat!important;filter:none!important;opacity:1!important;min-height:430px!important;position:relative!important;overflow:hidden!important}
.tm-ref-hero:before,.tm-ref-hero:after{display:none!important}.tm-ref-hero-inner,.tm-ref-mobile-picture-v20,.tm-ref-mobile-copy-v22,.tm-ref-dots{display:none!important}
@media(max-width:800px){.tm-ref-hero{height:285px!important;min-height:285px!important;background-position:center center!important}}
@media(max-width:430px){.tm-ref-hero{height:265px!important;min-height:265px!important}}
#tm-ai-float-v28{position:fixed;left:10px;bottom:18px;z-index:9997;border:0;background:transparent;padding:0;cursor:pointer;width:min(250px,58vw);filter:drop-shadow(0 12px 28px rgba(0,0,0,.34));transition:.2s transform ease}#tm-ai-float-v28:active{transform:scale(.97)}#tm-ai-float-v28 img{display:block;width:100%;height:auto}
#tm-ai-chat-v28{position:fixed;left:12px;bottom:96px;z-index:9998;width:min(390px,calc(100vw - 24px));max-height:min(620px,75vh);display:none;flex-direction:column;overflow:hidden;border-radius:24px;background:#0b0d10;color:#fff;border:1px solid rgba(247,197,62,.35);box-shadow:0 24px 70px rgba(0,0,0,.5);direction:rtl}#tm-ai-chat-v28.open{display:flex}
.tm-ai-head-v28{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;background:linear-gradient(135deg,#15181d,#090a0c);border-bottom:1px solid rgba(255,255,255,.08)}.tm-ai-head-v28 b{font-size:16px;color:#f7c53e}.tm-ai-head-v28 small{display:block;color:#aeb4bc;font-size:10px;margin-top:2px}#tm-ai-close-v28{border:0;background:#20242a;color:#fff;width:34px;height:34px;border-radius:50%;font-size:20px}
#tm-ai-log-v28{padding:14px;overflow:auto;display:flex;flex-direction:column;gap:10px;min-height:170px}.tm-ai-bubble-v28{max-width:88%;padding:10px 12px;border-radius:16px;font-size:12px;line-height:1.8}.tm-ai-bubble-v28.bot{align-self:flex-end;background:#161a20;border:1px solid rgba(247,197,62,.18)}.tm-ai-bubble-v28.user{align-self:flex-start;background:#f7c53e;color:#17120a;font-weight:800}.tm-ai-results-v28{display:grid;gap:8px}.tm-ai-item-v28{display:grid;grid-template-columns:48px 1fr auto;gap:8px;align-items:center;background:#11151a;border:1px solid rgba(255,255,255,.08);padding:8px;border-radius:14px}.tm-ai-item-v28 img{width:48px;height:48px;object-fit:contain;background:#fff;border-radius:9px}.tm-ai-item-v28 b{font-size:11px}.tm-ai-item-v28 span{font-size:10px;color:#f7c53e;white-space:nowrap}
.tm-ai-form-v28{display:flex;gap:8px;padding:10px;background:#0f1216;border-top:1px solid rgba(255,255,255,.08)}.tm-ai-form-v28 input{flex:1;min-width:0;height:44px;border:1px solid #2a3038;background:#fff;color:#111;border-radius:14px;padding:0 12px;font:inherit}.tm-ai-form-v28 button{border:0;border-radius:14px;padding:0 16px;background:#f7c53e;color:#17120a;font-weight:950}
@media(max-width:800px){#tm-ai-float-v28{width:min(190px,52vw);left:8px;bottom:10px}#tm-ai-chat-v28{left:8px;bottom:82px;width:calc(100vw - 16px);max-height:72vh}}
</style>'''
if '</head>' not in s: raise SystemExit('head close not found')
s=s.replace('</head>',css+'</head>',1)
widget=r'''<button id="tm-ai-float-v28" type="button" aria-label="باز کردن دستیار هوشمند"><img src="tehran_visual_asset.php?asset=ai&v=28" alt="دستیار هوشمند"></button><div id="tm-ai-chat-v28" aria-live="polite"><div class="tm-ai-head-v28"><div><b>دستیار هوشمند طهران مارکت</b><small>محصولی که می‌خواهی را بگو</small></div><button id="tm-ai-close-v28" type="button">×</button></div><div id="tm-ai-log-v28"><div class="tm-ai-bubble-v28 bot">سلام 👋 چی لازم داری؟ اسم محصول، برند یا دسته‌بندی را بنویس.</div></div><form class="tm-ai-form-v28" id="tm-ai-form-v28"><input id="tm-ai-input-v28" maxlength="120" autocomplete="off" placeholder="مثلاً شیر کم‌چرب، برنج، نوشابه..."><button type="submit">بگرد</button></form></div><script id="tm-ai-script-v28">(()=>{const fab=document.getElementById('tm-ai-float-v28'),box=document.getElementById('tm-ai-chat-v28'),close=document.getElementById('tm-ai-close-v28'),form=document.getElementById('tm-ai-form-v28'),inp=document.getElementById('tm-ai-input-v28'),log=document.getElementById('tm-ai-log-v28');if(!fab||!box||!form||!inp||!log)return;const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));const price=n=>Number(n||0).toLocaleString('fa-IR')+' تومان';function msg(t,who='bot'){const d=document.createElement('div');d.className='tm-ai-bubble-v28 '+who;d.textContent=t;log.appendChild(d);log.scrollTop=log.scrollHeight;return d}fab.onclick=()=>{box.classList.add('open');setTimeout(()=>inp.focus(),80)};close.onclick=()=>box.classList.remove('open');form.onsubmit=async e=>{e.preventDefault();const q=inp.value.trim();if(!q)return;msg(q,'user');inp.value='';const wait=msg('دارم بین محصولات می‌گردم…','bot');try{const r=await fetch('ai_assistant.php?action=search&q='+encodeURIComponent(q),{credentials:'same-origin',cache:'no-store'});const j=await r.json();wait.remove();if(!j.ok)throw new Error(j.message||'خطا');if(!Array.isArray(j.items)||!j.items.length){msg('چیزی با این مشخصات پیدا نکردم. اسم یا برند را کمی متفاوت بنویس.');return}const wrap=document.createElement('div');wrap.className='tm-ai-results-v28';j.items.slice(0,5).forEach(it=>{const d=document.createElement('div');d.className='tm-ai-item-v28';const img=it.image?`<img src="${esc(it.image)}" alt="">`:'<div style="width:48px;height:48px;background:#fff;border-radius:9px"></div>';d.innerHTML=img+`<b>${esc(it.name)}</b><span>${price(it.price)}</span>`;wrap.appendChild(d)});log.appendChild(wrap);log.scrollTop=log.scrollHeight}catch(err){wait.remove();msg('ارتباط با دستیار برقرار نشد. دوباره امتحان کن.')}}})();</script>'''
if '</body>' not in s: raise SystemExit('body close not found')
s=s.replace('</body>',widget+'</body>',1)
p.write_text(s,encoding='utf-8')
print('VISUAL_V28_OK')
